-- ============================================================================
-- FESE304 Week 8 Practice Pack: Normalization 1NF -> 2NF -> 3NF (`w08_normalization`)
-- Sources:
--   1. `raw_movies`: GroupLens MovieLens (`ml-latest-small/movies.csv`, first 1,000 movies)
--      License: GroupLens Educational Non-Commercial License
--   2. `raw_order_lines`: Olist Brazilian E-Commerce (1,200 real flat order-item rows)
--      License: CC BY-NC-SA 4.0
-- ============================================================================

DROP DATABASE IF EXISTS w08_normalization;
CREATE DATABASE w08_normalization CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE w08_normalization;

-- Table 1: Violates 1NF because `genres` stores pipe-separated repeating groups
-- (e.g., 'Adventure|Animation|Children|Comedy|Fantasy') in a single column.
CREATE TABLE `raw_movies` (
  `movie_id` INT NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `release_year` INT DEFAULT NULL,
  `genres` VARCHAR(255) NOT NULL,
  PRIMARY KEY (`movie_id`)
) ENGINE=InnoDB;

-- Table 2: In 1NF, with composite primary key (`order_id`, `order_item_id`),
-- but violates 2NF (partial dependencies on `order_id` alone) and
-- violates 3NF (transitive dependencies via `customer_id`, `product_id`, `seller_id`, and `product_category_pt`).
CREATE TABLE `raw_order_lines` (
  `order_id` CHAR(32) NOT NULL,
  `order_item_id` INT NOT NULL,
  `order_status` VARCHAR(20) NOT NULL,
  `order_purchase_timestamp` DATETIME NOT NULL,
  `customer_id` CHAR(32) NOT NULL,
  `customer_city` VARCHAR(100) NOT NULL,
  `customer_state` CHAR(2) NOT NULL,
  `product_id` CHAR(32) NOT NULL,
  `product_category_pt` VARCHAR(64) NOT NULL,
  `product_category_en` VARCHAR(64) NOT NULL,
  `seller_id` CHAR(32) NOT NULL,
  `seller_city` VARCHAR(100) NOT NULL,
  `seller_state` CHAR(2) NOT NULL,
  `price` DECIMAL(10,2) NOT NULL,
  `freight_value` DECIMAL(10,2) NOT NULL,
  PRIMARY KEY (`order_id`, `order_item_id`)
) ENGINE=InnoDB;










